 14→	let expanded = $state(block.status === 'running');
 15→
 16→	let borderColor = $derived(
 17→		block.status === 'completed'
 18→			? 'border-l-status-completed'
 19→			: block.status === 'failed'
 20→				? 'border-l-status-blocked'
 21→				: 'border-l-status-pending-review'
