 23→
 24→	let icon = $derived(getToolIcon(block.toolName));
 25→	let preview = $derived(getToolInputPreview(block.toolName, block.input));
 26→
 27→	function formatOutput(output: unknown): string {
 28→		if (typeof output === 'string') return output;
 29→		try {
 30→			return JSON.stringify(output, null, 2);
 31→		} catch {
 32→			return String(output);
 33→		}
 34→	}
 35→
 36→	function formatInput(input: unknown): string {
 37→		if (typeof input === 'string') return input;
 38→		try {
 39→			return JSON.stringify(input, null, 2);
 40→		} catch {
 41→			return String(input);
 42→		}
 43→	}
 44→
 45→	let outputText = $derived(block.output ? formatOutput(block.output) : '');
 46→	let truncatedOutput = $derived(
 47→		outputText.length > 1000 ? outputText.slice(0, 1000) : outputText
 48→	);
 49→	let isOutputTruncated = $derived(outputText.length > 1000);
 50→	let showFullOutput = $state(false);
 51→</script>
 52→
 53→<div
 54→	class="border-l-2 {borderColor} rounded-r-md bg-card/50"
 55→	data-testid="tool-call-block"
 56→	data-tool-call-id={block.toolCallId}
 57→>
 58→	<!-- Header (always visible) -->
 59→	<button
 60→		class="flex items-center gap-2 w-full px-3 py-2 text-left text-sm hover:bg-accent/30 transition-colors"
 61→		onclick={() => (expanded = !expanded)}
 62→		aria-expanded={expanded}
 63→	>
 64→		<ChevronRight
 65→			class="size-3.5 text-muted-foreground transition-transform {expanded ? 'rotate-90' : ''}"
 66→		/>
 67→
 68→		<span class="text-xs text-muted-foreground font-mono">{formatTime(block.startedAt)}</span>
