 79→		{:else if block.status === 'failed'}
 80→			<X class="size-3.5 text-status-blocked" />
 81→		{/if}
 82→
 83→		{#if !expanded && preview}
 84→			<span class="text-xs text-muted-foreground truncate flex-1">{preview}</span>
 85→		{/if}
 86→
 87→		{#if block.durationMs !== undefined}
 88→			<span class="text-[10px] text-muted-foreground font-mono ml-auto flex-shrink-0">
 89→				{formatDuration(block.durationMs)}
 90→			</span>
 91→		{/if}
 92→	</button>
 93→
 94→	<!-- Expanded content -->
 95→	{#if expanded}
 96→		<div class="px-3 pb-3 space-y-2">
 97→			{#if block.input}
 98→				<div>
 99→					<p class="text-[10px] font-medium text-muted-foreground uppercase tracking-wide mb-1">Input</p>
100→					<pre class="text-xs font-mono bg-secondary/50 rounded p-2 overflow-x-auto max-h-60 whitespace-pre-wrap break-words">{formatInput(block.input)}</pre>
101→				</div>
102→			{/if}
103→
104→			{#if block.output !== undefined}
105→				<div>
106→					<p class="text-[10px] font-medium text-muted-foreground uppercase tracking-wide mb-1">
107→						Output
108→						{#if block.status === 'failed'}
109→							<span class="text-destructive">(error)</span>
110→						{/if}
111→					</p>
112→					<pre class="text-xs font-mono bg-secondary/50 rounded p-2 overflow-x-auto max-h-80 whitespace-pre-wrap break-words {block.status === 'failed' ? 'text-destructive' : ''}">{showFullOutput ? outputText : truncatedOutput}</pre>
113→					{#if isOutputTruncated && !showFullOutput}
114→						<button
115→							class="text-xs text-primary hover:underline mt-1"
116→							onclick={() => (showFullOutput = true)}
117→						>
118→							Show full output ({outputText.length.toLocaleString()} chars)
119→						</button>
120→					{/if}
121→				</div>
122→			{/if}
123→		</div>
124→	{/if}
125→</div>
126→
